// swift-tools-version: 5.9

import Foundation
import PackageDescription

// ROS 2 interfaces from outside common_interfaces (control_msgs, moveit_msgs, and the
// object_recognition_msgs and octomap_msgs types moveit_msgs uses) for Swift, one module per
// ROS package, generated by swift-ros2-gen from the upstream IDL pinned in idl.lock.
// Each module holds the types listed in the README, not the whole upstream package. Depends
// only on swift-ros2-rosidl and swift-ros2-common-interfaces, so it never downloads native
// frameworks.

var dependencies: [Package.Dependency] = [
    .package(url: "https://github.com/swift-ros2/swift-ros2-rosidl.git", from: "1.1.1"),
    .package(url: "https://github.com/swift-ros2/swift-ros2-common-interfaces.git", from: "1.0.0"),
]
if ProcessInfo.processInfo.environment["SWIFT_ROS2_DOCS_BUILD"] == "1" {
    dependencies.append(.package(url: "https://github.com/apple/swift-docc-plugin", from: "1.3.0"))
}

func rosidl(_ name: String) -> Target.Dependency {
    .product(name: name, package: "swift-ros2-rosidl")
}

func common(_ name: String) -> Target.Dependency {
    .product(name: name, package: "swift-ros2-common-interfaces")
}

let core: [Target.Dependency] = [rosidl("SwiftROS2CDR"), rosidl("SwiftROS2Messages")]

// Every module a generated file imports must be listed, or the module does not build.
let interfaces: [(name: String, dependencies: [Target.Dependency])] = [
    ("ControlMsgs", [rosidl("BuiltinInterfaces"), rosidl("UniqueIdentifierMsgs")]),
    (
        "MoveitMsgs",
        [
            rosidl("BuiltinInterfaces"), rosidl("UniqueIdentifierMsgs"), common("StdMsgs"), common("GeometryMsgs"),
            common("SensorMsgs"), common("ShapeMsgs"), common("TrajectoryMsgs"), "ObjectRecognitionMsgs",
            "OctomapMsgs",
        ]
    ),
    ("ObjectRecognitionMsgs", []),
    ("OctomapMsgs", [common("StdMsgs"), common("GeometryMsgs")]),
]
let allInterfaces: [Target.Dependency] = interfaces.map { .target(name: $0.name) }
// The modules of the referenced types, for the oracle corpus and the tests.
let referenced: [Target.Dependency] = [
    rosidl("BuiltinInterfaces"), rosidl("UniqueIdentifierMsgs"), common("StdMsgs"), common("GeometryMsgs"),
    common("SensorMsgs"), common("ShapeMsgs"), common("TrajectoryMsgs"),
]

let package = Package(
    name: "swift-ros2-extra-interfaces",
    platforms: [.iOS(.v16), .macOS(.v13), .macCatalyst(.v16), .visionOS(.v1)],
    products: interfaces.map { .library(name: $0.name, targets: [$0.name]) },
    dependencies: dependencies,
    targets: interfaces.map { .target(name: $0.name, dependencies: core + $0.dependencies) }
        + [
            .executableTarget(name: "ExtraInterfacesOracleCorpus", dependencies: core + allInterfaces + referenced),
            .testTarget(name: "ExtraInterfacesTests", dependencies: core + allInterfaces + referenced),
        ]
)
